SourceCode.Declaration:
public class METTMSEngineHeaderSalesOrderContract extends METTMSEngineHeaderContract
{
    METSalesTable metSalesTable;
    METSalesOrderTypes salesOrderTypes;

}

Method.Source:
/// <summary>
///
/// </summary>
/// <returns></returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = metSalesTable.StagingLaneId;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public Common getExtensionTable()
{
    Common ret;

    ret = metSalesTable;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METTMSShipmentID getShipmentID()
{
    if(!shipmentId)
    {
        str shippingDateStr = date2Str
        (sourceRecord.getShipDate(),
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

        shipmentId = strFmt("@MET:ShipmentStrFmt",
        sourceRecord.InventLocationFrom,
        sourceRecord.CustomerAccount,
        sourceRecord.Route,
        shippingDateStr);
    }

    return super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public TransDate getReceiptDate()
{
    TransDate ret;

    ret = super();

    if(!ret)
    {
        ret = sourceRecord.RequestedReceiptDate;
    }

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METRouteStopNum getRouteStop()
{
    METRouteStopNum ret = sourceRecord.RouteStop;

    return ret;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean isOrderExcluded()
{
    boolean ret = false;

    if(!salesOrderTypes)
    {
        salesOrderTypes = METSalesOrderTypes::find(sourceRecord.OrderType);
    }

    if (salesOrderTypes.RecId)
    {
        ret = salesOrderTypes.ExcludeFromTMSEngine;
    }

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public TransDate getShipDate()
{
    TransDate ret;

    ret = super();

    if(!ret)
    {
        ret = sourceRecord.RequestedShipDate;
    }

    return ret;
}

/// <summary>
/// Gets the customer account of the order
/// </summary>
/// <returns>Customer account number</returns>
public CustAccount getCustomerAccount()
{
    return sourceRecord.CustomerAccount;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public NoYes isInternalCrossDockOrder()
{
    NoYes ret;

    ret = metSalesTable.InternalCrossDockOrder;

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = metSalesTable.OriginalRouteStopIdentifier;

    return ret;
}

/// <summary>
/// Get the route identifier of the order
/// </summary>
/// <returns>Route identifier</returns>
public METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = metSalesTable.OriginalRouteIdentifier;

    return ret;
}

/// <summary>
/// Gets the carrier code of the order
/// </summary>
/// <returns>Carrier code</returns>
public TMSCarrierCode getCarrierCode()
{
    TMSCarrierCode ret;

    if(!carrierCode)
    {
        carrierCode = TMSSalesTable::find(sourceRecord.OrderId).CarrierCode;
    }

    ret = super();

    return ret;
}
